body:
> can be easily removed, but won't change much

Patch to remove all non-Android stuff (including docs), for the reference:

<details>
  <summary>Patch</summary>
  
```diff
diff --git a/editor/export/editor_export_platform_apple_embedded.cpp b/editor/export/editor_export_platform_apple_embedded.cpp
index 9c33eda5c1..c5637b3da1 100644
--- a/editor/export/editor_export_platform_apple_embedded.cpp
+++ b/editor/export/editor_export_platform_apple_embedded.cpp
@@ -1827,11 +1827,9 @@ Error EditorExportPlatformAppleEmbedded::_export_project_helper(const Ref<Editor
 	if (ep.step("Making .pck", 0)) {
 		return ERR_SKIP;
 	}
-	bool sparse = p_preset->has("binary_format/sparse_pck") && p_preset->get("binary_format/sparse_pck");
-
-	String pack_path = binary_dir + (sparse ? ".sparsepck" : ".pck");
+	String pack_path = binary_dir + ".pck";
 	Vector<SharedObject> libraries;
-	Error err = save_pack(p_preset, p_debug, pack_path, &libraries, nullptr, nullptr, false, nullptr, nullptr, sparse);
+	Error err = save_pack(p_preset, p_debug, pack_path, &libraries);
 	if (err) {
 		// Message is supplied by the subroutine method.
 		return err;
diff --git a/editor/export/editor_export_platform_pc.cpp b/editor/export/editor_export_platform_pc.cpp
index 2adca33b0a..d3a1b97acd 100644
--- a/editor/export/editor_export_platform_pc.cpp
+++ b/editor/export/editor_export_platform_pc.cpp
@@ -58,7 +58,6 @@ void EditorExportPlatformPC::get_export_options(List<ExportOption> *r_options) c
 	r_options->push_back(ExportOption(PropertyInfo(Variant::INT, "debug/export_console_wrapper", PROPERTY_HINT_ENUM, "No,Debug Only,Debug and Release"), 1));
 
 	r_options->push_back(ExportOption(PropertyInfo(Variant::BOOL, "binary_format/embed_pck"), false));
-	r_options->push_back(ExportOption(PropertyInfo(Variant::BOOL, "binary_format/sparse_pck"), false));
 
 	r_options->push_back(ExportOption(PropertyInfo(Variant::BOOL, "texture_format/s3tc_bptc"), true));
 	r_options->push_back(ExportOption(PropertyInfo(Variant::BOOL, "texture_format/etc2_astc"), false));
@@ -124,11 +123,6 @@ bool EditorExportPlatformPC::has_valid_export_configuration(const Ref<EditorExpo
 		err += TTR("A texture format must be selected to export the project. Please select at least one texture format.");
 	}
 
-	if (p_preset->get("binary_format/embed_pck") && p_preset->get("binary_format/sparse_pck")) {
-		valid = false;
-		err += TTR("Embedded PCK can't be sparse.");
-	}
-
 	if (!err.is_empty()) {
 		r_error = err;
 	}
@@ -207,20 +201,18 @@ Error EditorExportPlatformPC::prepare_template(const Ref<EditorExportPreset> &p_
 }
 
 Error EditorExportPlatformPC::export_project_data(const Ref<EditorExportPreset> &p_preset, bool p_debug, const String &p_path, BitField<EditorExportPlatform::DebugFlags> p_flags) {
-	bool sparse = p_preset->has("binary_format/sparse_pck") && p_preset->get("binary_format/sparse_pck");
-
 	String pck_path;
 	if (p_preset->get("binary_format/embed_pck")) {
 		pck_path = p_path;
 	} else {
-		pck_path = p_path.get_basename() + (sparse ? ".sparsepck" : ".pck");
+		pck_path = p_path.get_basename() + ".pck";
 	}
 
 	Vector<SharedObject> so_files;
 
 	int64_t embedded_pos;
 	int64_t embedded_size;
-	Error err = save_pack(p_preset, p_debug, pck_path, &so_files, nullptr, nullptr, p_preset->get("binary_format/embed_pck"), &embedded_pos, &embedded_size, sparse);
+	Error err = save_pack(p_preset, p_debug, pck_path, &so_files, nullptr, nullptr, p_preset->get("binary_format/embed_pck"), &embedded_pos, &embedded_size);
 	if (err == OK && p_preset->get("binary_format/embed_pck")) {
 		if (embedded_size >= 0x100000000 && String(p_preset->get("binary_format/architecture")).contains("32")) {
 			add_message(EXPORT_MESSAGE_ERROR, TTR("PCK Embedding"), TTR("On 32-bit exports the embedded PCK cannot be bigger than 4 GiB."));
diff --git a/editor/export/project_export.cpp b/editor/export/project_export.cpp
index 6b64feeb13..d632e45a5e 100644
--- a/editor/export/project_export.cpp
+++ b/editor/export/project_export.cpp
@@ -1265,14 +1265,8 @@ void ProjectExportDialog::_export_pck_zip_selected(const String &p_path) {
 		} else {
 			platform->export_pack(current, export_debug, p_path);
 		}
-	} else if (p_path.ends_with(".sparsepck")) {
-		if (export_as_patch) {
-			platform->export_pack_patch(current, export_debug, p_path, Vector<String>(), 0, true);
-		} else {
-			platform->export_pack(current, export_debug, p_path, 0, true);
-		}
 	} else {
-		ERR_FAIL_MSG("Path must end with .pck, .sparsepck or .zip");
+		ERR_FAIL_MSG("Path must end with .pck or .zip");
 	}
 }
 
@@ -1790,7 +1784,6 @@ ProjectExportDialog::ProjectExportDialog() {
 	export_pck_zip = memnew(EditorFileDialog);
 	export_pck_zip->add_filter("*.zip", TTR("ZIP File"));
 	export_pck_zip->add_filter("*.pck", TTR("Godot Project Pack"));
-	export_pck_zip->add_filter("*.sparsepck", TTR("Godot Sparse Project Pack"));
 	export_pck_zip->set_access(EditorFileDialog::ACCESS_FILESYSTEM);
 	export_pck_zip->set_file_mode(EditorFileDialog::FILE_MODE_SAVE_FILE);
 	add_child(export_pck_zip);
